/**
 * Materialise the opt-in goal extension into the pi carrier.
 *
 * Three rules, and each one exists because its absence was a real failure elsewhere in this codebase:
 *
 * 1. **Opt-in only.** A project that has not set `goal.enabled` gets nothing. `engram` is published
 *    to other people's repositories; running lifecycle code in all of them is not a side effect a
 *    scaffolder may have.
 * 2. **Only a generated file is ever written or removed.** The header is matched as a whole line, so
 *    a hand-written extension next to ours — or one whose prose merely mentions the marker — is never
 *    touched. Same rule as `prune-carriers.ts`, and for the same reason.
 * 3. **The write is symlink-guarded.** `.pi/extensions/` is exactly the kind of directory people
 *    redirect elsewhere (`writeFileGuarded`), and this file runs on every settlement boundary.
 */

import path from 'node:path';
import { isDir, pathExists, readFileSafe, resolvesInsideRoot, writeFileGuarded } from '../core/project.js';
import { promises as fs } from 'node:fs';
import {
  GOAL_EXTENSION_HEADER,
  GOAL_EXTENSION_PATH,
  goalExtensionSource,
  type GoalExtensionContext,
} from '../templates/goal-extension.js';

/**
 * The carrier's generated header, matched as a whole line.
 *
 * `content.includes(GOAL_EXTENSION_HEADER)` would classify a hand-written extension whose prose
 * merely *mentions* the marker as generated, and deleting it is the one mistake that loses user code.
 */
export type GoalCarrierAction = 'written' | 'unchanged' | 'removed' | 'kept-foreign' | 'refused';

export interface GoalCarrierResult {
  action: GoalCarrierAction;
  path: string;
  /** Set when the file was left alone for a reason the caller should print. */
  note?: string;
  /**
   * True when `action` describes what a real run *would* do.
   *
   * Without this the CLI printed `removed .pi/extensions/engram-goal.ts` on a `--dry-run` and the file
   * was still there — a report that lies in the direction of the destructive operation.
   */
  planned: boolean;
}

/**
 * Is the file at the carrier path one engram wrote?
 *
 * The match is deliberately narrow: the first line must be engram's header **followed by the version
 * stamp this generator emits**. A `startsWith(GOAL_EXTENSION_HEADER)` check accepted a hand-written
 * file whose first line read `// generated by engram is a lie — this is mine`, and `--goal off` then
 * deleted user code. Only the exact provenance engram stamps counts.
 */
async function isGenerated(root: string): Promise<boolean> {
  const content = await readFileSafe(path.join(root, GOAL_EXTENSION_PATH));
  if (content === null) return false;
  const first = (content.split('\n')[0] ?? '').trimStart();
  return first.startsWith(`${GOAL_EXTENSION_HEADER} @zeroicey/engram@`);
}

async function removeIfEmpty(dir: string): Promise<void> {
  try {
    if ((await fs.readdir(dir)).length === 0) await fs.rmdir(dir);
  } catch {
    /* non-empty or gone: nothing to do */
  }
}

export async function syncGoalCarrier(
  root: string,
  enabled: boolean,
  ctx: GoalExtensionContext,
  dryRun = false,
): Promise<GoalCarrierResult> {
  const abs = path.join(root, GOAL_EXTENSION_PATH);
  const exists = await pathExists(abs);
  const generated = exists && (await isGenerated(root));

  if (!enabled) {
    // Turning the opt-in off must actually remove the hook. Leaving a file behind that calls a CLI
    // the project no longer wants is the worst of both states.
    if (!exists) return { action: 'unchanged', path: GOAL_EXTENSION_PATH, planned: false };
    if (!generated) {
      return {
        action: 'kept-foreign',
        path: GOAL_EXTENSION_PATH,
        note: 'not generated by engram — left untouched (delete it yourself if it is stale)',
        planned: false,
      };
    }
    if (!dryRun) {
      await fs.rm(abs, { force: true });
      await removeIfEmpty(path.dirname(abs));
    }
    return { action: 'removed', path: GOAL_EXTENSION_PATH, planned: dryRun };
  }

  // A pi carrier in a project with a hand-written extension at the same path: refuse rather than
  // overwrite. There is no merge that is safe here — the file would register twice.
  if (exists && !generated) {
    return {
      action: 'kept-foreign',
      path: GOAL_EXTENSION_PATH,
      note: 'a hand-written file already exists at this path — move it, then re-run `engram sync`',
      planned: false,
    };
  }

  // `.pi/extensions` must be a directory, not a file: `writeFileGuarded` would otherwise throw
  // EEXIST/ENOTDIR from inside `fs` instead of reporting the shape problem.
  if (await pathExists(path.dirname(abs))) {
    if (!(await isDir(path.dirname(abs)))) {
      return {
        action: 'refused',
        path: GOAL_EXTENSION_PATH,
        note: '.pi/extensions exists but is not a directory',
        planned: false,
      };
    }
  }

  const content = goalExtensionSource(ctx);
  const existing = exists ? await readFileSafe(abs) : null;
  if (existing === content) return { action: 'unchanged', path: GOAL_EXTENSION_PATH, planned: false };
  // The symlink guard runs *here*, before the dry-run branch: `planned` promises what a real run would
  // do, and returning `written` first meant `--dry-run` reported a success the real run refuses.
  if (!(await resolvesInsideRoot(root, abs))) {
    return {
      action: 'refused',
      path: GOAL_EXTENSION_PATH,
      note: 'refusing to write through a symlinked directory — nothing outside the project is modified',
      planned: false,
    };
  }
  if (dryRun) return { action: 'written', path: GOAL_EXTENSION_PATH, planned: true };
  if (!(await writeFileGuarded(root, abs, content))) {
    return {
      action: 'refused',
      path: GOAL_EXTENSION_PATH,
      note: 'refusing to write through a symlinked directory — nothing outside the project is modified',
      planned: false,
    };
  }
  return { action: 'written', path: GOAL_EXTENSION_PATH, planned: false };
}
